import {externalGearPair, sliderCrank} from '/leitor/mechanics.mjs'
export const train = externalGearPair({teethA:20,teethB:40,module:1.5,samples:8})
export const initial = () => ({angle:36,playing:false,locked:false,detail:false})
export function pose(state) {
  const angle=state.angle*Math.PI/180, angles=train.phaseAt(angle)
  const linkage=sliderCrank({radius:8,rodLength:30,side:-1},angle)
  return {angles,linkage,driven:-state.angle*train.ratio}
}
export function step(state,action,value) {
  if(action==='reset') return initial()
  if(action==='lock') return {...state,locked:!state.locked,playing:false}
  if(action==='detail') return {...state,detail:!state.detail}
  if(state.locked) return state
  if(action==='angle') return {...state,angle:Math.max(0,Math.min(720,Number(value)||0)),playing:false}
  if(action==='play') return {...state,playing:!state.playing}
  if(action==='advance') return {...state,angle:(state.angle+30)%720}
  return state
}
export function advance(state,delta) {
  if(!state.playing||state.locked) return state
  return {...state,angle:(state.angle+Math.max(0,Math.min(.05,delta))*30)%720}
}

