import * as k from '/kit/iso-kit.mjs'
import * as G from '/kit/lathe.mjs'
import {mPrism,mItems,mSvg,mArc} from '/kit/facets.mjs'
import {train,pose} from './model.mjs'
const circle=r=>mArc(0,0,r,0,2*Math.PI,40).slice(0,-1)
const frame=(x,y,z,angle=0)=>({o:[x,y,z],u:[Math.cos(angle),Math.sin(angle),0],v:[-Math.sin(angle),Math.cos(angle),0],a:[0,0,1]})
const project=(p,P)=>k.iso(p,P)
const path=(points,P,closed=true)=>k.pathOf(points.map(p=>project(p,P)),closed)
function slot(a,b,r) {
  const phi=Math.atan2(b[1]-a[1],b[0]-a[0]),points=[]
  for(let i=0;i<=16;i++){const q=phi-Math.PI/2+Math.PI*i/16;points.push([b[0]+r*Math.cos(q),b[1]+r*Math.sin(q)])}
  for(let i=0;i<=16;i++){const q=phi+Math.PI/2+Math.PI*i/16;points.push([a[0]+r*Math.cos(q),a[1]+r*Math.sin(q)])}
  return points
}
export function draw(state) {
  const p=pose(state),detail=state.detail
  const bounds=detail?k.boxCorners({x:7,y:-13,w:22,d:26},19,30):[
    ...k.boxCorners({x:-46,y:-33,w:125,d:66},-2,2),
    ...k.boxCorners({x:-16.5,y:-16.5,w:33,d:33},20,27),
    ...k.boxCorners({x:13.5,y:-31.5,w:63,d:63},20,27),
    ...k.boxCorners({x:-44,y:-9,w:29,d:18},2,35),
    ...k.boxCorners({x:-10,y:-10,w:20,d:20},29,35)]
  const P=k.fitProjection(bounds,900,430,{pad:detail?85:30,azimuth:detail?0:75,elevation:detail?88:42})
  let layers=[]
  const solid=(shape,tone='mid')=>layers.push(k.solidSvg(shape,{tone,crease:'faint'}))
  const mesh=(rings,F,s0,s1,tone='mid')=>layers.push(mSvg(mItems(mPrism(rings,F,s0,s1,{tone}),P)[0]))
  if(!detail){
    solid(k.slabOf({x:-46,y:-33,w:125,d:66,r:4},-2,4,P,8,1),'lo')
    for(const x of [-40,72])for(const y of [-27,27]){
      solid(k.cylinder(x,y,2.5,2,1.2,P,20,.25),'lo')
      layers.push(k.lineSvg(k.segment([x-1,y,3.3],[x+1,y,3.3],P),{tone:'mid'}))
    }
    for(const x of [0,train.distance]){
      solid(k.cylinder(x,0,6.5,2,9,P,40,1),'mid')
      solid(k.cylinder(x,0,4.5,11,20,P,32,.4),'hi')
    }
    // Guide rails end below the connecting rod plane and pass through the
    // two actual slider bushings. Slider's pin is in the rod's z=32 plane.
    for(const y of [-5,5])solid(G.disc(-43,-17,1.2,G.frameAlong([0,y,29],[1,0,0]),P),'mid')
    for(const x of [-42,-18])solid(k.slabOf({x:x-2,y:-9,w:4,d:18,r:1},2,28,P,4,.3),'lo')
  }
  // Both gears occupy the SAME XY frame, share a pitch tangent, and rotate
  // according to the exact phase pair. True concave meshes retain tooth gaps.
  for(const [gear,x,angle] of [[train.first,0,p.angles[0]],[train.second,train.distance,p.angles[1]]]) {
    const windows=gear.teeth===40?Array.from({length:4},(_,i)=>{
      const start=i*Math.PI/2+.22,end=(i+1)*Math.PI/2-.22
      return [...mArc(0,0,23,start,end,12),...mArc(0,0,8,end,start,12)]
    }):[]
    mesh([gear.outline,circle(3.2),...windows],frame(x,0,0,angle),20,24,'hi')
    if(!detail){
      solid(k.cylinder(x,0,5,24,3,P,32,.4),'hi')
      const mark=[x+gear.pitchRadius*.76*Math.cos(angle),gear.pitchRadius*.76*Math.sin(angle),24.03]
      const mark2=[x+gear.pitchRadius*.94*Math.cos(angle),gear.pitchRadius*.94*Math.sin(angle),24.03]
      layers.push(`<path d="${path([mark,mark2],P,false)}" class="bench-accent"/>`)
      for(let i=0;i<3;i++){
        const a=angle+i*2*Math.PI/3
        solid(k.cylinder(x+7*Math.cos(a),7*Math.sin(a),.9,24,1,P,12,.1),'lo')
      }
    }
  }
  if(detail){
    for(const [center,r] of [[[0,0,24.04],train.first.pitchRadius],[[train.distance,0,24.04],train.second.pitchRadius]]){
      layers.push(`<path d="${path(circle(r).map(([x,y])=>[x+center[0],y,center[2]]),P)}" class="bench-pitch"/>`)
    }
  }else{
    solid(k.cylinder(0,0,3,27,5,P,32,.3),'hi')
    mesh([slot([0,0],p.linkage.pin,3)],frame(0,0,0),29,31,'hi')
    // The slider, crank pin and rod are all derived from the same closure.
    const [sx]=p.linkage.slider
    solid(k.slabOf({x:sx-4,y:-7,w:8,d:14,r:1.4},27,4,P,6,.5),'hi')
    mesh([slot(p.linkage.pin,p.linkage.slider,2)],frame(0,0,0),31,33,'hi')
    for(const [x,y] of [p.linkage.pin,p.linkage.slider]){
      solid(k.cylinder(x,y,1.5,29,5,P,20,.2),'hi')
      solid(k.cylinder(x,y,2.1,34,1,P,24,.2),'mid')
    }
  }
  return `<svg class="iso-svg" role="img" aria-label="${detail?'Detalhe dos dentes engrenados':'Engrenagens acopladas a uma biela e cursor'}" viewBox="0 0 900 430">${layers.join('')}</svg>`
}

