import {initial,pose,step,advance} from './model.mjs'
import {draw} from './geometry.mjs'
export function mount(root,env){
  let state=initial(),visible=true,reduced=env.reducedMotion,last=0,raf=0,disposed=false
  root.innerHTML=`<section class="bench"><header class="bench-head"><span>ESTUDO MECÂNICO · 01</span><span>20 : 40</span></header><div id="bench-art"></div><div class="bench-readings"><div><span>Entrada</span><output id="bench-input"></output></div><div><span>Saída</span><output id="bench-output"></output></div><div><span>Curso do cursor</span><output id="bench-travel"></output></div></div><div class="bench-controls"><button id="bench-play">Iniciar</button><button id="bench-lock" aria-pressed="false">Travar</button><button id="bench-detail" aria-pressed="false">Ver dentes</button><button id="bench-reset">Reiniciar</button></div><label class="bench-angle" for="bench-angle">Girar o eixo<span>0–720°</span></label><input id="bench-angle" type="range" min="0" max="720" value="36" step="1"><p id="bench-status" aria-live="polite"></p><p class="bench-note">A engrenagem de 20 dentes dá duas voltas para a de 40 completar uma. A biela transforma o giro em um curso de 16 mm.</p></section>`
  const q=s=>root.querySelector(s),art=q('#bench-art')
  function render(){
    const p=pose(state)
    art.innerHTML=draw(state)
    q('#bench-input').textContent=`${state.angle.toFixed(0)}°`
    q('#bench-output').textContent=`${p.driven.toFixed(0)}°`
    q('#bench-travel').textContent=`${p.linkage.displacement.toFixed(1)} / 16 mm`
    q('#bench-angle').value=String(state.angle)
    q('#bench-lock').setAttribute('aria-pressed',String(state.locked))
    q('#bench-detail').setAttribute('aria-pressed',String(state.detail))
    q('#bench-detail').textContent=state.detail?'Ver conjunto':'Ver dentes'
    q('#bench-play').textContent=reduced?'Avançar 30°':state.playing?'Pausar':'Iniciar'
    q('#bench-status').textContent=state.locked?'Eixo travado · destrave para girar':state.detail?'Dentes em detalhe · círculos primitivos tracejados':state.playing?'Em movimento · relação 2:1':'Pausado · arraste para explorar'
  }
  function tick(now){
    raf=0
    if(disposed||!visible||reduced||!state.playing)return
    state=advance(state,last?(now-last)/1000:0);last=now;render();raf=requestAnimationFrame(tick)
  }
  function schedule(){cancelAnimationFrame(raf);raf=0;last=0;if(visible&&!reduced&&state.playing)raf=requestAnimationFrame(tick)}
  const click=e=>{const id=e.target.closest('button')?.id;if(!id)return
    const action={'bench-play':reduced?'advance':'play','bench-lock':'lock','bench-detail':'detail','bench-reset':'reset'}[id]
    if(action){state=step(state,action);render();schedule()}}
  const input=e=>{if(e.target.id==='bench-angle'){state=step(state,'angle',e.target.value);render();schedule()}}
  const environment=e=>{visible=e.detail.visible!==false;reduced=Boolean(e.detail.reducedMotion);root.dataset.theme=e.detail.theme;render();schedule()}
  root.addEventListener('click',click);root.addEventListener('input',input);root.addEventListener('figure:environment',environment)
  render()
  return()=>{disposed=true;cancelAnimationFrame(raf);root.removeEventListener('click',click);root.removeEventListener('input',input);root.removeEventListener('figure:environment',environment);root.replaceChildren()}
}
